diff --git a/drivers/net/tun.c b/drivers/net/tun.c
index cd0fbf9b0a22d3a41b0b4de6408423ec591e8d55..cd6b6d3fd4e2c9dc0a19a947dd4468b60c07dc0d 100644
--- a/drivers/net/tun.c
+++ b/drivers/net/tun.c
@@ -1656,6 +1656,9 @@ static int tun_set_iff(struct net *net, struct file *file, struct ifreq *ifr)

 		if (!dev)
 			return -ENOMEM;
+		err = dev_get_valid_name(net, dev, name);
+		if (err)
+			goto err_free_dev;

 		dev_net_set(dev, net);
 		dev->rtnl_link_ops = &tun_link_ops;
diff --git a/include/linux/netdevice.h b/include/linux/netdevice.h
index 49ac10f99da0e92aa74d17fff5abe9e3988b86ec..de98fd0fc5b0380f0cf283f7f6651f34e8c07592 100644
--- a/include/linux/netdevice.h
+++ b/include/linux/netdevice.h
@@ -3245,6 +3245,9 @@ struct net_device *alloc_netdev_mqs(int sizeof_priv, const char *name,
 				    unsigned char name_assign_type,
 				    void (*setup)(struct net_device *),
 				    unsigned int txqs, unsigned int rxqs);
+int dev_get_valid_name(struct net *net, struct net_device *dev,
+		       const char *name);
+
 #define alloc_netdev(sizeof_priv, name, name_assign_type, setup) \
 	alloc_netdev_mqs(sizeof_priv, name, name_assign_type, setup, 1, 1)

diff --git a/net/core/dev.c b/net/core/dev.c
index 21b0bd976699d899e1620537ede50dfceed82ec2..93e36e9102e96b850c65651d3c5946a8b40cecbd 100644
--- a/net/core/dev.c
+++ b/net/core/dev.c
@@ -1059,9 +1059,8 @@ static int dev_alloc_name_ns(struct net *net,
 	return ret;
 }

-static int dev_get_valid_name(struct net *net,
-			      struct net_device *dev,
-			      const char *name)
+int dev_get_valid_name(struct net *net, struct net_device *dev,
+		       const char *name)
 {
 	BUG_ON(!net);

@@ -1077,6 +1076,7 @@ static int dev_get_valid_name(struct net *net,

 	return 0;
 }
+EXPORT_SYMBOL(dev_get_valid_name);

